        fs::create_dir_all(dir.join("pages").join("sub")).unwrap();
        fs::write(
            dir.join("pages").join("sub").join("Nested.md"),
            "- nested\n",
        )
        .unwrap();
        fs::write(dir.join("journals").join("2026_06_26.org"), "* canonical\n").unwrap();
