        assert!(Graph::open(&equal)
            .initial_shadow_raw_managed_text_inventory()
            .unwrap()
            .is_empty());

        let retarget = scratch("initial-shadow-configured-retarget");
        fs::create_dir_all(retarget.join("logseq")).unwrap();
